//! `row_to_fault` — pure mapping of a fetched `faults` row into a [`crate::Fault`], the crate-root
//! sibling of the fingerprint helpers already lifted out of `lib.rs`. No IO: the row is already
//! materialized, so the store's read paths compose this without a database in the test.
use crate::Fault;

pub(crate) fn row_to_fault(r: &rusqlite::Row) -> rusqlite::Result<Fault> {
    Ok(Fault {
        fingerprint: r.get(0)?,
        stage: r.get(1)?,
        level: r.get(2)?,
        title: r.get(3)?,
        sample_stack: r.get(4)?,
        source_hint: r.get(5)?,
        release: r.get(6)?,
        count: r.get(7)?,
        first_seen: r.get(8)?,
        last_seen: r.get(9)?,
        resolved_at: r.get(10)?,
    })
}
